#include "symrep_bootstrap.hpp"
using namespace symrep;
int main(int argc,char**argv){try{require(argc==2,"usage local_TR_gate OUT");fs::path out=argv[1];rref_option_t opt;opt->pool.reset(1);auto start=std::chrono::steady_clock::now();auto tf=read_matrix(out/"boundary_local_rref.wxf"),J=read_matrix(out/"suffix_TR92_to_TF175.wxf");auto embedding=kron(identity(88),J);auto raw=mul(tf,transpose(embedding));write(out/"boundary_local_TR_raw.wxf",raw);std::cout<<"PROJECT rows="<<raw.nrow<<" cols="<<raw.ncol<<" nnz="<<raw.nnz()<<" seconds="<<seconds(start)<<std::endl;
 auto rr=raw;rr.sort_rows_by_nnz();auto piv=sparse_mat_rref_reconstruct(rr,opt);std::map<I,size_t>where;std::vector<I>oldrows;for(auto&batch:piv)for(auto[r,c]:batch){where[c]=oldrows.size();oldrows.push_back(r);}Mat b(oldrows.size(),raw.ncol);for(size_t r=0;r<b.nrow;++r)b[r]=std::move(rr[oldrows[r]]);rr.clear();Mat C(raw.nrow,b.nrow);for(size_t r=0;r<raw.nrow;++r)for(auto[c,x]:raw[r])if(where.contains(c))C[r].push_back(index(where[c]),x);for(auto&r:C.rows)normalize(r);require(equal(mul(C,b),raw),"local TR exact row reconstruction");for(size_t r=0;r<b.nrow;++r)for(auto[c,x]:b[r])if(where.contains(c))require(where[c]==r&&x==1,"rank basis identity pivot block");write(out/"boundary_local_TR_rref.wxf",b);write(out/"boundary_local_TR_coefficients.wxf",C);std::cout<<"RREF rank="<<b.nrow<<" nnz="<<b.nnz()<<" exact_all_rows=pass seconds="<<seconds(start)<<std::endl;
 auto L=kernel(transpose(C),opt);require(L.nrow==raw.nrow-b.nrow,"leftnull dimension");require(mul(L,C).nnz()==0,"exact leftnull coordinates");require(mul(L,raw).nnz()==0,"exact leftnull physical restriction");write(out/"boundary_local_TR_leftnull.wxf",L);auto gate=mul(L,tf);require(mul(gate,transpose(embedding)).nnz()==0,"gate annihilates homogeneous TR");write(out/"boundary_local_TR_affine_gate.wxf",gate);std::ofstream j(out/"boundary_local_TR_gate.json");j<<"{\"all_checks_pass\":true,\"TF_local_dimensions\":["<<tf.nrow<<','<<tf.ncol<<"],\"TR_raw_dimensions\":["<<raw.nrow<<','<<raw.ncol<<"],\"TR_rank\":"<<b.nrow<<",\"leftnull_dimension\":"<<L.nrow<<",\"leftnull_nonzeros\":"<<L.nnz()<<",\"affine_gate_nonzeros\":"<<gate.nnz()<<",\"exact_certificates\":[\"raw=C.rref\",\"RREF pivot block=identity\",\"L.C=0\",\"L.raw=0\",\"gate=L.TF_local\",\"gate.(id88 tensor J)^T=0\"],\"scope\":\"Necessary local affine consistency gate on the particular origin. No contraction with a weight8 origin or global solving performed here.\",\"seconds\":"<<seconds(start)<<"}\n";std::cout<<"COMPLETE leftnull="<<L.nrow<<" gate_nnz="<<gate.nnz()<<" seconds="<<seconds(start)<<std::endl;
}catch(const std::exception&e){std::cerr<<e.what()<<std::endl;return 1;}return 0;}
